1	import test from 'node:test';
2	import assert from 'node:assert/strict';
3	import { executeWorkflow, executeWorkflowAsync } from '../src/engine.js';
4	
5	// Regression coverage for form defaults aimed at a structured input whose
6	// prototype already answers the field's name with an inherited member — most
7	// importantly a Map, whose prototype exposes "size" as an accessor with no
8	// setter. Only own properties count as filled: the inherited Map.prototype.size
9	// neither substitutes for a missing field nor makes a legal default throw
10	// (a plain [[Set]] finds the getter-only prototype property and raises a
11	// TypeError). The default is installed as an own enumerable data property
12	// instead, the Map keeps its type and original entries, and every existing
13	// rollback, copy and isolation rule keeps working.
14	
15	function oneFormWorkflow(fields, formId = 'collect') {
16	  return {
17	    id: 'prototype-defaults',
18	    entry: 'start',
19	    nodes: [
20	      { id: 'start', type: 'trigger', next: formId },
21	      { id: formId, type: 'form', next: 'done', schema: { fields } },
22	      { id: 'done', type: 'end', result: 'ok' },
23	    ],
24	  };
25	}
26	
27	// start -> form-one (defaults shadow inherited Map members) -> gate
28	//       -> act (business op reading the defaults on its own copy) -> done
29	function gatedWorkflow() {
30	  return {
31	    id: 'prototype-defaults-async',
32	    entry: 'start',
33	    nodes: [
34	      { id: 'start', type: 'trigger', next: 'form-one' },
35	      { id: 'form-one', type: 'form', next: 'gate', schema: { fields: [
36	        { path: 'request.options.size', type: 'integer', default: 7 },
37	        { path: 'request.options.size2.label', type: 'string', default: 'manual' },
38	      ] } },
39	      {
40	        id: 'gate', type: 'condition', then: 'act', else: 'missed',
41	        condition: { all: [
42	          { field: 'request.options.size', operator: 'eq', value: 7 },
43	          { field: 'request.options.size2.label', operator: 'eq', value: 'manual' },
44	        ] },
45	      },
46	      { id: 'act', type: 'action', operation: 'inspect', next: 'done' },
47	      { id: 'missed', type: 'end', result: 'condition-saw-inherited' },
48	      { id: 'done', type: 'end', result: 'finished' },
49	    ],
50	  };
51	}
52	
53	function assertMapWithOwnDefaults(map, { size = 7, expectSize2 = true } = {}) {
54	  assert.ok(map instanceof Map, 'the value keeps its Map type');
55	  assert.equal(Object.hasOwn(map, 'size'), true, 'size is an own field');
56	  assert.equal(map.size, size, 'the own field shadows Map.prototype.size');
57	  assert.deepEqual([...map.entries()], [['a', 1], ['b', 2]], 'original Map members survive');
58	  if (expectSize2) {
59	    assert.deepEqual(map.size2, { label: 'manual' }, 'the created own parent chain reads through');
60	  }
61	}
62	
63	test('sync: a default shadows an inherited read-only/accessor property instead of throwing', () => {
64	  const callerMap = new Map([['a', 1], ['b', 2]]);
65	  const caller = { request: { options: callerMap } };
66	  const result = executeWorkflow(oneFormWorkflow([
67	    { path: 'request.options.size', type: 'integer', default: 7 },
68	  ]), caller);
69	
70	  assert.equal(result.status, 'completed');
71	  assert.equal(result.result, 'ok');
72	  assertMapWithOwnDefaults(result.context.input.request.options, { expectSize2: false });
73	
74	  // The caller's Map was never mutated: no own "size", prototype getter intact.
75	  assert.equal(Object.hasOwn(callerMap, 'size'), false);
76	  assert.equal(callerMap.size, 2);
77	  assert.deepEqual([...callerMap.entries()], [['a', 1], ['b', 2]]);
78	});
79	
80	test('sync: a default path creates the missing own parent rather than descending the prototype', () => {
81	  // A populated Map answers "size" on its prototype with a number; the default
82	  // path size.label must not walk into that number (and then fail assigning to
83	  // it) — the missing own parent is created as a fresh plain object.
84	  const callerMap = new Map([['a', 1]]);
85	  const result = executeWorkflow(oneFormWorkflow([
86	    { path: 'request.options.size.label', type: 'string', default: 'manual' },
87	  ]), { request: { options: callerMap } });
88	
89	  assert.equal(result.status, 'completed');
90	  const options = result.context.input.request.options;
91	  assert.ok(options instanceof Map);
92	  assert.equal(Object.hasOwn(options, 'size'), true);
93	  assert.equal(Object.getPrototypeOf(options.size), Object.prototype);
94	  assert.equal(options.size.label, 'manual');
95	  // The inherited member count never substituted for — or blocked — the field.
96	  assert.equal(options.size !== 1, true);
97	  assert.deepEqual([...options.entries()], [['a', 1]]);
98	  assert.equal(Object.hasOwn(callerMap, 'size'), false);
99	});
100	
101	test('sync and async use the same behavior', async () => {
102	  const workflow = oneFormWorkflow([
103	    { path: 'request.options.size', type: 'integer', default: 7 },
104	    { path: 'request.options.size2.label', type: 'string', default: 'manual' },
105	  ]);
106	  const make = () => ({ request: { options: new Map([['a', 1], ['b', 2]]) } });
107	
108	  const sync = executeWorkflow(workflow, make());
109	  assert.equal(sync.status, 'completed');
110	  assertMapWithOwnDefaults(sync.context.input.request.options);
111	
112	  const async = await executeWorkflowAsync(workflow, make(), {});
113	  assert.equal(async.status, 'completed');
114	  assertMapWithOwnDefaults(async.context.input.request.options);
115	});
116	
117	test('async: conditions and business copies read the defaults; copy edits stay in the copy', async () => {
118	  const callerMap = new Map([['a', 1], ['b', 2]]);
119	  const caller = { request: { options: callerMap } };
120	  let attemptCopy;
121	  const result = await executeWorkflowAsync(gatedWorkflow(), caller, {
122	    inspect: (input, output, nodeId, attempt) => {
123	      const options = input.request.options;
124	      assertMapWithOwnDefaults(options);
125	      attemptCopy = input;
126	      assert.equal(nodeId, 'act');
127	      assert.equal(attempt, 1);
128	      // Edit every part of this invocation's copy.
129	      options.size = 700;
130	      options.size2.label = 'changed';
131	      options.set('copy-only', true);
132	      options.addedOwnProp = true;
133	      return { saw: options.size };
134	    },
135	  });
136	
137	  assert.equal(result.status, 'completed');
138	  assert.equal(result.result, 'finished', 'the condition read the own defaults, not inherited size');
139	  assert.deepEqual(result.trace.map(n => n.nodeId), ['start', 'form-one', 'gate', 'act', 'done']);
140	  assert.deepEqual(result.context.output.act, { saw: 700 });
141	
142	  // The live run input keeps the defaults and the original entries.
143	  assertMapWithOwnDefaults(result.context.input.request.options);
144	  const live = result.context.input.request.options;
145	  assert.equal(live.has('copy-only'), false);
146	  assert.equal(Object.hasOwn(live, 'addedOwnProp'), false);
147	
148	  // The attempt's own copy keeps its independent edits.
149	  assert.equal(attemptCopy.request.options.size, 700);
150	  assert.equal(attemptCopy.request.options.size2.label, 'changed');
151	  assert.equal(attemptCopy.request.options.has('copy-only'), true);
152	
153	  // The caller's Map is completely untouched.
154	  assert.equal(Object.hasOwn(callerMap, 'size'), false);
155	  assert.equal(callerMap.size, 2);
156	  assert.deepEqual([...callerMap.entries()], [['a', 1], ['b', 2]]);
157	});
