159	test('a failed form rolls the shadowing default and its created parents back in declaration order', async () => {
160	  const workflow = {
161	    id: 'prototype-defaults-rollback',
162	    entry: 'start',
163	    nodes: [
164	      { id: 'start', type: 'trigger', next: 'form-a' },
165	      { id: 'form-a', type: 'form', next: 'act', schema: { fields: [
166	        { path: 'earlier.keep', type: 'integer', default: 1 },
167	      ] } },
168	      { id: 'act', type: 'action', message: 'saved-output', next: 'form-b' },
169	      { id: 'form-b', type: 'form', next: 'done', schema: { fields: [
170	        { path: 'request.options.size', type: 'integer', default: 7 },
171	        { path: 'request.options.size2', type: 'integer', default: 8 },
172	        { path: 'request.options.deep.label', type: 'string', default: 'manual' },
173	        { path: 'missing.required', type: 'string', required: true },
174	      ] } },
175	      { id: 'done', type: 'end', result: 'should-not-happen' },
176	    ],
177	  };
178	
179	  for (const [label, run] of [
180	    ['sync', input => executeWorkflow(workflow, input)],
181	    ['async', input => executeWorkflowAsync(workflow, input, {})],
182	  ]) {
183	    const callerMap = new Map([['k', 'v']]);
184	    const caller = { request: { options: callerMap } };
185	    const result = await run(caller);
186	
187	    assert.equal(result.status, 'invalid_input', label);
188	    assert.deepEqual(result.errors, [
189	      { nodeId: 'form-b', path: 'missing.required', code: 'required' },
190	    ], `${label}: errors keep declaration order`);
191	    assert.deepEqual(result.trace.map(n => n.nodeId),
192	      ['start', 'form-a', 'act', 'form-b'], `${label}: later nodes do not run`);
193	    assert.equal(result.result, undefined, label);
